select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'sha256',encode(extensions.digest(trim(replace(pg_get_functiondef(p.oid),chr(13),'')),'sha256'),'hex')) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname||'.'||p.proname in ('public.upsert_editorial_research_source','public.get_research_review_context','public.save_research_review','private.rad_rich_text','private.rad_apply_rich_patches','private.rad_project_rich','public.get_structured_article_context','public.propose_structured_research','public.get_research_review_context_v2','private.rad_structured_accept_guard','public.save_structured_research_review','public.review_research_proposal');